import {isBackground,backgroundMarkup,drawBackground} from './background-layout.js?v=36';
import {chooseSharing} from './sharing.js?v=33';
import {mountPhoneSelector,modelVariant,prepareModelColor,phoneColor} from './phone-models.js?v=36';
import {createEditor} from './editor.js?v=38';
import {templates,stickers,designFor} from './flow-assets/catalog.js';
const main=document.querySelector('#flow-main'),actions=document.querySelector('#flow-actions');
let lang=window.PopomoLocale.get();
const t=(zh,en)=>lang==='en'?en:zh;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data;try{const r=await fetch('./flow-assets/data.json');if(!r.ok)throw Error();data=await r.json();}catch{main.innerHTML='<p class="loading">目录暂时无法加载，请刷新重试。<br>Catalog unavailable. Please reload.</p>';throw Error('Catalog unavailable');}
let launchSource='';
const query=new URLSearchParams(location.search),validTemplate=id=>templates.some(x=>x.id===id);
let state={entryTemplate:query.get('design')||null,model:'',phoneColor:'blue',brand:data.models[0]?.brand||'Apple',template:validTemplate(query.get('design'))?query.get('design'):'bloom',background:'#30b7b9',layers:[],mainTab:'materials',subTab:'templates',selected:null,aiStyle:data.styles[0]?.code,aiPhoto:'',aiResult:'',uploadAs:'background'};
function templateLayers(id){return designFor(id).layers.map(l=>({...l,scale:1,src:l.type==='sticker'?stickers.find(s=>s.id===l.asset)?.src:l.src}));}
state.layers=templateLayers(state.template);state.background=designFor(state.template).background;
try{const saved=JSON.parse(sessionStorage.getItem('popomo-flow-draft'));if(saved&&(!query.has('entry')||saved.homeEntry===query.get('entry'))&&data.models.some(m=>m.name===saved.model)&&(!query.has('design')||saved.entryTemplate===query.get('design')))state={...state,...saved};}catch{}
if(query.has('entry')&&state.homeEntry!==query.get('entry')){try{const entry=JSON.parse(sessionStorage.getItem('popomo-design-entry'));if(entry?.id===query.get('entry')&&['template','photo','ai'].includes(entry.source)){launchSource=entry.launchSource||'';if(entry.flowState&&Array.isArray(entry.flowState.layers)){state={...state,...entry.flowState,homeEntry:entry.id,savedDesignId:entry.designId||entry.flowState.savedDesignId,designName:entry.name};}else{state.savedDesignId=entry.designId||entry.id;state.designName=entry.name;state.printerId=entry.printerId;state.model=data.models.some(m=>m.name===entry.model)?entry.model:'';state.phoneColor=entry.phoneColor||'blue';state.brand=data.models.find(m=>m.name===state.model)?.brand||state.brand;state.homeEntry=entry.id;if(entry.source==='template'&&validTemplate(entry.template)){state.template=entry.template;state.entryTemplate=entry.template;state.background=designFor(entry.template).background;const factor=(entry.zoom||100)/100;state.layers=templateLayers(entry.template).map(l=>({...l,x:50+(l.x-50)*factor,y:50+(l.y-50)*factor,scale:factor,origin:'preset'}));}else{state.background='#faf9f5';state.layers=(entry.backgroundImage||entry.image)?[{id:'photo-background',type:'image',src:entry.backgroundImage||entry.image,x:50,y:50,size:100,scale:1,rotation:0,origin:'background'}]:[];state.aiPhoto=entry.source==='ai'?entry.image:'';}state.editor={source:entry.source,drafts:{},photoDraft:null,aiDraft:null};}}}catch{}}
if(state.homeEntry){try{sessionStorage.setItem('popomo-flow-draft',JSON.stringify(state));}catch{}}

let step='model',undo=null,pendingTemplate=null,consent=false,saved=false,toastTimer,aiTimer,aiBusy=false;
const model=()=>modelVariant(data.models.find(m=>m.name===state.model)||data.models[0],state.phoneColor);
function persist(){try{sessionStorage.setItem('popomo-flow-draft',JSON.stringify(state));}catch{}const next=document.querySelector('#next-step');if(next&&step==='design')next.disabled=!state.layers.some(l=>l.origin==='background'||l.origin==='preset');}
function toast(zh,en){const el=document.querySelector('#flow-toast');el.textContent=t(zh,en);el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000);}
function caseHTML(m,layers=state.layers,bg=state.background,editable=false){return `<div class="case-shell" style="--ratio:${m.width/m.height}"><div class="case-print" style="background:${esc(bg)};mask-image:url('${esc(m.mask)}');-webkit-mask-image:url('${esc(m.mask)}')">${layers.map(l=>{if(isBackground(l))return backgroundMarkup(l,m);const style=`${l.id==='photo-background'?'height:100%;':''}--x:${l.x};--y:${l.y};--size:${l.size};--rotation:${l.rotation||0};--scale:${l.scale||1};${l.type==='text'?`color:${esc(l.color||'#263e34')};font-family:${l.font==='sans'?'Arial,sans-serif':l.font==='hand'?'cursive':l.font==='mono'?'monospace':'Georgia,serif'};`:''}`;const content=l.type==='text'?esc(l.text):`<img src="${esc(l.src)}" alt="" draggable="false" ${l.id==='photo-background'?'style="height:100%;object-fit:cover"':''}>`;return editable?`<button class="case-layer ${l.type==='text'?'text-layer':''}" style="${style}" data-layer="${esc(l.id)}" aria-label="${esc(l.type==='text'?l.text:t('图案','Graphic'))}" aria-pressed="${l.id===state.selected}">${content}</button>`:`<div class="case-layer ${l.type==='text'?'text-layer':''}" style="${style}">${content}</div>`;}).join('')}</div><img class="case-overlay" src="${esc(m.overlay)}" alt="${esc(m.name)}" draggable="false"></div>`;}
function setStep(next,push=true){if(step==='design')editor.beforeLeave();if(!state.model&&next!=='model')next='model';if(next!=='review'){consent=false;saved=false;}step=next;if(push)history.pushState(null,'','#'+next);render();window.scrollTo({top:0,behavior:'instant'});if(next==='design'){const heading=main.querySelector('h1');heading.tabIndex=-1;heading.focus({preventScroll:true});}else main.focus({preventScroll:true});}
window.addEventListener('popstate',()=>setStep(location.hash.slice(1),false));
document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>setStep(b.dataset.step)));
function render(){lang=window.PopomoLocale?.get()||lang;document.body.dataset.flowStep=step;if(!['model','design','review'].includes(step))step='model';document.documentElement.lang=lang==='en'?'en':'zh-CN';document.documentElement.dataset.language=lang;document.querySelector('#flow-language').value=lang;document.querySelector('.exit-link')?.setAttribute('aria-label',t('返回首页','Back to home'));document.querySelectorAll('[data-zh]').forEach(el=>el.textContent=el.dataset[lang==='en'?'en':'zh']);document.querySelectorAll('[data-step]').forEach((b,i)=>{const current=['model','design','review'].indexOf(step);b.setAttribute('aria-current',i===current?'step':'false');b.disabled=i>0&&!state.model;b.classList.toggle('completed',i<current);b.querySelector('span').textContent=i<current?'✓':String(i+1);});main.classList.remove('layout-enter');main.innerHTML=(step==='model'?modelPage():step==='design'?designPage():reviewPage());actions.innerHTML=actionBar();requestAnimationFrame(()=>main.classList.add('layout-enter'));bind();}

function modelPage(){return `<div class="page-heading"><p class="eyebrow">YOUR PERFECT FIT</p><h1>${t('选择你的机型与颜色。','Your phone. Your color.')}</h1><p class="subcopy">${t('选择完整型号，再挑选你手机的颜色。','Choose the exact model, then pick your phone color.')}</p></div><div class="phone-model-page"><section><h2>${t('手机型号','Phone model')}</h2><div id="flow-phone-selector"></div></section><div class="phone-model-live-preview">${caseHTML(model(),[],'#f4eaff')}<p>${esc(state.model||t('选择你的手机型号','Choose your phone model'))}</p><span>${t(phoneColor(state.phoneColor).zh,phoneColor(state.phoneColor).en)}</span></div></div>`;}
function reviewPage(){return `<div class="page-heading"><p class="eyebrow">ONE LAST LITTLE LOOK</p><h1>${t('每个细节，都喜欢吗？','Happy with every little detail?')}</h1><p class="subcopy">${t('确认手机型号和图案位置，尤其留意镜头开孔。','Check your phone model, artwork and camera cutout.')}</p></div><div class="review-layout"><div class="design-stage review-stage">${caseHTML(model())}</div><section class="review-summary"><h2>${t('你的专属设计','Your one-of-a-kind design')}</h2><div class="review-row"><span>${t('手机型号','Phone model')}</span><strong>${esc(state.model)}</strong></div><div class="review-row"><span>${t('手机机身颜色','Phone body color')}</span><strong>${t(phoneColor(state.phoneColor).zh,phoneColor(state.phoneColor).en)}</strong></div><div class="review-row"><span>${t('设计方式','Design method')}</span><strong>${t('自定义设计','Custom design')}</strong></div><div class="review-row"><span>${t('打印数量','Quantity')}</span><strong>1 ${t('个手机壳','case')}</strong></div><hr><div class="review-row"><span>${t('打印价格','Print price')}</span><strong>$${esc(data.price)}</strong></div>${saved?`<div class="saved-note" role="status">✓ ${t('设计已保存，你可以继续编辑或下载设计图。','Design saved. Continue editing or download your design.')}<br><button class="undo-button tertiary" id="download-preview">↓ ${t('下载预览图','Download preview')}</button></div>`:''}</section></div>`;}
function actionBar(){if(step==='model')return `<div class="action-summary">${state.model?esc(state.model):t('请选择手机型号','Choose your phone model')}<small>${state.model?t('已选择 · 可随时返回更改','Selected · Change it anytime'):t('先选品牌，再选型号','Brand first, then model')}</small></div><button class="primary" id="next-step" ${!state.model?'disabled':''}>${t('开始设计','Start designing')} <span aria-hidden="true">→</span></button>`;if(step==='design')return `<button class="back-button tertiary" id="back-step">← ${t('返回','Back')}</button><button class="primary" id="next-step" ${!editor.canContinue()?'disabled':''}>${t('预览确认','Review')} <span aria-hidden="true">→</span></button>`;return `<button class="tertiary review-edit" id="back-step">← ${t('继续编辑','Keep editing')}</button><div class="review-save-actions"><button class="secondary" id="save-draft">${t('保存设计草稿','Save draft')}</button><button class="primary" id="confirm-print" ${savingDesign||!editor.canContinue()?'disabled':''}>${t('直接打印','Print now')} <span aria-hidden="true">→</span></button></div>`;}
function bindActions(){document.querySelector('#next-step')?.addEventListener('click',()=>setStep(step==='model'?'design':'review'));document.querySelector('#back-step')?.addEventListener('click',()=>setStep(step==='design'?'model':'design'));document.querySelector('#save-draft')?.addEventListener('click',saveDesign);document.querySelector('#confirm-print')?.addEventListener('click',confirmPrint);}

async function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=src;});}
async function renderDesignCanvas(){const m=model(),canvas=document.createElement('canvas');canvas.width=m.width;canvas.height=m.height;const ctx=canvas.getContext('2d');ctx.fillStyle=state.background;ctx.fillRect(0,0,canvas.width,canvas.height);for(const l of state.layers){if(isBackground(l)){drawBackground(ctx,await loadImage(l.src),l,m);continue;}ctx.save();ctx.translate(l.x/100*canvas.width,l.y/100*canvas.height);ctx.rotate((l.rotation||0)*Math.PI/180);ctx.scale(l.scale||1,l.scale||1);if(l.type==='text'){ctx.fillStyle=l.color||'#263e34';ctx.font=`600 ${l.size*.0015*canvas.width}px ${l.font==='sans'?'Arial':l.font==='hand'?'cursive':l.font==='mono'?'monospace':'Georgia'}`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(l.text,0,0);}else{const im=await loadImage(l.src),w=l.size/100*canvas.width;if(l.id==='photo-background'){const h=canvas.height,factor=Math.max(w/im.width,h/im.height);const sw=w/factor,sh=h/factor;ctx.drawImage(im,(im.width-sw)/2,(im.height-sh)/2,sw,sh,-w/2,-h/2,w,h);}else ctx.drawImage(im,-w/2,-w*im.height/im.width/2,w,w*im.height/im.width);}ctx.restore();}ctx.globalCompositeOperation='destination-in';ctx.drawImage(await loadImage(m.mask),0,0,canvas.width,canvas.height);ctx.globalCompositeOperation='source-over';ctx.drawImage(await loadImage(m.overlay),0,0,canvas.width,canvas.height);return canvas;}
async function downloadPreview(){try{const canvas=await renderDesignCanvas();canvas.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='POPOMO-preview.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}catch{toast('预览图暂时无法下载，请重试','Could not download the preview. Please try again.');}}
let savingDesign=false;
async function persistCurrentDesign(sharing={}){const canvas=await renderDesignCanvas();state.savedDesignId=state.savedDesignId||crypto.randomUUID();const cover=canvas.toDataURL('image/webp',.85);const design=window.PopomoDesigns.save({id:state.savedDesignId,name:state.designName||t('我的定制设计','My custom design'),model:state.model,phoneColor:state.phoneColor,printerId:state.printerId,source:state.editor?.source||'template',template:state.template,image:cover,cover,zoom:100,position:50,flowState:structuredClone(state),...sharing});saved=true;persist();return design;}
function disableSaveActions(){document.querySelectorAll('#save-draft,#confirm-print').forEach(button=>button.disabled=true);}
function showDraftSaved(design){
 const dialog=document.createElement('dialog');dialog.className='saved-design-dialog';dialog.setAttribute('aria-labelledby','saved-design-title');dialog.setAttribute('aria-describedby','saved-design-description');
 dialog.innerHTML=`<button class="saved-design-close" aria-label="${t('关闭','Close')}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button><div class="saved-design-check" aria-hidden="true"><svg viewBox="0 0 32 32"><path d="m8 16 5 5 11-12"/></svg></div><h2 id="saved-design-title">${t('设计草稿保存成功','Design draft saved')}</h2><p id="saved-design-description">${t('已保存到我的设计，可继续编辑或前往打印。','Saved to My designs. Edit it anytime or print it now.')}</p><div class="saved-design-item"><img src="${esc(design.cover||design.image)}" alt=""><div><strong>${esc(design.name)}</strong><span>${esc(design.model)}</span></div></div><div class="saved-design-actions"><a class="secondary" href="./my-designs.html" data-view-saved>${t('查看设计草稿作品','View designs')}</a><button class="primary" data-print-saved>${t('去打印','Print now')} →</button></div><p class="saved-print-error" role="alert"></p>`;
 let printing=false;const view=dialog.querySelector('[data-view-saved]'),print=dialog.querySelector('[data-print-saved]');
 view.addEventListener('click',e=>{if(printing)e.preventDefault();});
 print.onclick=()=>{if(printing)return;printing=true;print.disabled=true;view.setAttribute('aria-disabled','true');print.textContent=t('正在准备订单…','Preparing order…');try{const order=window.PopomoOrders.create(design,Math.round(Number(data.price)*100));location.href='./checkout.html?order='+encodeURIComponent(order.id);}catch{printing=false;print.disabled=false;view.removeAttribute('aria-disabled');print.textContent=t('去打印','Print now')+' →';dialog.querySelector('.saved-print-error').textContent=t('暂时无法创建订单，请重试。草稿已保存。','Could not create the order. Your draft is saved; please retry.');}};
 dialog.querySelector('.saved-design-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});document.body.append(dialog);dialog.showModal();
}
async function saveDesign(){if(savingDesign)return;savingDesign=true;disableSaveActions();let design;try{const sharing=await chooseSharing(t);if(sharing)design=await persistCurrentDesign(sharing);}catch{toast('暂时无法保存，请重试','Could not save. Please retry.');}finally{savingDesign=false;render();}if(design)showDraftSaved(design);}
async function confirmPrint(){if(savingDesign||!state.model||!editor.canContinue())return;savingDesign=true;disableSaveActions();const button=document.querySelector('#confirm-print');if(button)button.textContent=t('正在准备订单…','Preparing order…');try{const design=await persistCurrentDesign();const order=window.PopomoOrders.create(design,Math.round(Number(data.price)*100));location.href='./checkout.html?order='+encodeURIComponent(order.id);}catch{savingDesign=false;render();toast('暂时无法创建订单，请重试','Could not create order. Please retry.');}}

await prepareModelColor(data.models.find(m=>m.name===state.model)||data.models[0],state.phoneColor);

function changeEditorPhone(){
 editor.beforeLeave();
 const opener=document.querySelector('[data-model-edit]');
 const dialog=document.createElement('dialog');dialog.className='editor-phone-dialog';dialog.setAttribute('aria-labelledby','editor-phone-title');
 dialog.innerHTML=`<header><h2 id="editor-phone-title">${t('切换机型与颜色','Change phone & color')}</h2><button type="button" data-phone-close aria-label="${t('关闭','Close')}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header><div data-editor-phone-picker></div><footer><button type="button" class="primary" data-home-model-next>${t('确认切换','Apply changes')} →</button></footer>`;
 let pendingModel=data.models.find(m=>m.name===state.model)||data.models[0],pendingColor=state.phoneColor;
 mountPhoneSelector(dialog.querySelector('[data-editor-phone-picker]'),{models:data.models,value:pendingModel.name,color:pendingColor,t,onChange:(m,c)=>{pendingModel=m;pendingColor=c;}});
 dialog.querySelector('[data-phone-close]').onclick=()=>dialog.close();
 dialog.querySelector('[data-home-model-next]').onclick=()=>{state.model=pendingModel.name;state.brand=pendingModel.brand;state.phoneColor=pendingColor;persist();dialog.close();render();document.querySelector('[data-model-edit]')?.focus({preventScroll:true});};
 dialog.addEventListener('close',()=>{dialog.remove();if(opener?.isConnected)opener.focus({preventScroll:true});},{once:true});
 document.body.append(dialog);dialog.showModal();
}

if(state.editor)state.editor={drafts:{},photoDraft:null,aiDraft:null,...state.editor};
const editor=createEditor({state,t,model,persist,toast,goModel:changeEditorPhone});
function designPage(){return editor.html();}
function bind(){
 bindActions();
 const selector=main.querySelector('#flow-phone-selector');if(selector)mountPhoneSelector(selector,{models:data.models,value:state.model,color:state.phoneColor,t,onChange:async(m,c)=>{state.model=m.name;state.brand=m.brand;state.phoneColor=c;persist();render();}});
 document.querySelector('#download-preview')?.addEventListener('click',downloadPreview);
 if(step==='design'){editor.bind();if(launchSource){const source=launchSource;launchSource='';editor.openSource(source);}}
}
const initialStep=location.hash.slice(1)||(query.has('entry')&&state.homeEntry===query.get('entry')&&data.models.some(m=>m.name===state.model)?'design':'model');
setStep(initialStep,false);

window.PopomoLocale.subscribe(()=>render());
